def solve(g):
    n=len(g);m=len(g[0])
    seen=set();out=[r[:] for r in g]
    for i in range(n):
        for j in range(m):
            if g[i][j]==0 and (i,j) not in seen:
                comp=[(i,j)];seen.add((i,j));k=0;border=False
                while k<len(comp):
                    a,b=comp[k];k+=1
                    if a in(0,n-1) or b in(0,m-1):border=True
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<n and 0<=y<m and g[x][y]==0 and (x,y) not in seen:
                            seen.add((x,y));comp.append((x,y))
                if not border:
                    v=min(len(comp),3)+1
                    for a,b in comp:out[a][b]=v
    return out
